mapper.select:
select material_id, tenant_id, certification_id, merchant_id, product_id,
       material_kind, material_type, original_name, storage_path, content_type,
       file_extension, size_bytes, sha256, page_count, material_sort
from shop_product_certification_material
where material_id = #{materialId} and certification_id = #{certificationId}
  and merchant_id = #{merchantId} and product_id = #{productId}
  and material_kind = #{materialKind}

select certification_id from shop_product_certification
where current_flag = '1' and status = 'PASSED' and expires_at <= sysdate()
order by expires_at, certification_id limit #{limit}
